  useEffect(()=>{if(step==="trial-result"&&trt==="culturant"){const t=setTimeout(()=>pcs(),400);return()=>clearTimeout(t);}},[step,trt,pcs]);
  useEffect(()=>{if(ct===1&&step==="distribute"){ss("distributing");}},[ct]);
  useEffect(()=>{if(step==="distribute"&&ct>1){const t=setTimeout(()=>{ss("distributing");setTimeout(()=>sdp("after"),80);},2000);return()=>clearTimeout(t);}},[step,ct]);
  useEffect(()=>{if(dp==="after"){const nF=Math.max(dA?cs.coinB:cs.coinA,1);const dur=Math.max(90,Math.min(220,900/nF));const fA=dA?tot:0,fB=dA?0:tot;setDCa(fA);setDCb(fB);let s=0;const iv=setInterval(()=>{s++;const p=Math.min(s/nF,1);setDCa(Math.round(fA+(cs.coinA-fA)*p));setDCb(Math.round(fB+(cs.coinB-fB)*p));if(s>=nF){clearInterval(iv);setTimeout(()=>{setDCa(null);setDCb(null);},400);}},dur);return()=>clearInterval(iv);}},[dp,rk]);
