  const next=()=>{sj(null);spj(null);sp2(null);spp(null);spb([]);sdb(null);srk(0);sdp("before");if(ct>=TT){nav(`${bp}/end?coins=${coins}&piggyBank=${pig}`);return;}ss("distribute");nav(`${bp}/flow-vertical?round=${ct+1}&sequence=${seq}`,{replace:true});};
  const hP=(p:boolean)=>{sp2(p);if(p){scl(true);pps();setTimeout(()=>scl(false),600);sc(x=>x-1);spb(["Você perdeu 1 moeda"]);}setTimeout(()=>{spp(p);if(p){spb(x=>[...x,`${pn} perdeu 1 moeda`]);sdb(`${dn} perdeu 3 moedas`);spcl(true);setTimeout(()=>spcl(false),600);spc(x=>x-1);}setTimeout(()=>{if(eCC(p)){spig(x=>x+3);str("culturant");ss("trial-result");}else next();},3000);},3000);};
